/* «Город Слов» (русский, 3 класс) — данные, выгруженные из старой игры как есть.
 * ITEMS — все задания; id совпадают со старой версией (по ним переносятся коробки «знаю»).
 * Типы: dict, vow, pre, pref, part, odd, err, goal, mark, addr, phr, mem, syn, ant, fig, fraz, sec, mnog, trio.
 * Подробности по каждому типу — docs/games.md. Добавлять задания можно прямо сюда (id — уникальный). */
/* eslint-disable */

export interface SlovaStreet {
  id: string;
  name: string;
  sign: string;
  c: string;
  desc: string;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type SlovaItem = Record<string, any> & { id: string; type: string; street: string; label: string };

