export const RULES: Record<string, { title: string; text: string }> = {"dict": {"title": "Словарное слово", "text": "Словарное слово <b>нельзя проверить</b> — его запоминают. Прочитай слово <b>по слогам так, как оно пишется</b>, и запомни трудную букву."}, "vow": {"title": "Проверь ударением", "text": "Безударную гласную в корне проверяем так: <b>меняем слово</b>, чтобы эта гласная стала <b>ударной</b>. Проверочное слово — родственное, с тем же смыслом. Если в проверочном слове слышится <b>ё</b>, пишем <b>е</b>: пчёлы → пчела."}, "pre": {"title": "Приставки пишутся одинаково", "text": "Приставки <b>о-, об-, от-, до-, по-, под-, про-, за-, на-, над-, с-</b> пишутся <b>всегда одинаково</b>, как бы их ни слышали. Слышим «падбежал» — пишем <b>под</b>бежал. Слышим «атбежал» — пишем <b>от</b>бежал. Слышим «зделал» — пишем <b>с</b>делал: приставки «з-» нет. Сначала найди приставку — потом пиши."}, "pref": {"title": "Как найти приставку", "text": "Найди <b>корень</b> — общую часть родственных слов (бежал, бег). Всё, что стоит <b>перед корнем</b>, — приставка: <b>у</b>бежал, <b>про</b>бежал, <b>вы</b>бежал."}, "part": {"title": "Части слова", "text": "<b>Приставка</b> — перед корнем (<b>под</b>ход). <b>Корень</b> — общая часть родственных слов (<b>лес</b>, <b>лес</b>ник). <b>Суффикс</b> — после корня, делает новое слово (дом<b>ик</b>). <b>Окончание</b> — меняется, когда меняем слово (рыбк<b>а</b> — рыбк<b>и</b>)."}, "odd": {"title": "Родственные слова", "text": "У родственных (однокоренных) слов <b>общий корень и общий смысл</b>. Лесник работает в лесу — родственник. А лестница с лесом никак не связана — лишнее слово."}, "err": {"title": "Проверяй как учитель", "text": "Не торопись. Найди в слове <b>опасное место</b>: безударную гласную, приставку или трудную букву словарного слова. <b>Проверь его правилом</b> и только потом решай. Безударную гласную проверяй <b>проверочным словом</b>: гласная в нём под ударением."}, "goal": {"title": "Цель предложения", "text": "<b>Повествовательное</b> — рассказывает, в конце <b>точка</b>. <b>Вопросительное</b> — спрашивает (кто? где? когда? почему?), в конце <b>?</b> <b>Побудительное</b> — просит, приказывает, советует (закрой, помоги, не шумите), в конце <b>точка</b> или <b>!</b>, если говорим громко, с чувством."}, "mark": {"title": "Знак в конце", "text": "Рассказываем спокойно — <b>точка</b>. Спрашиваем — <b>вопросительный знак</b>. Говорим с сильным чувством — радостью, восхищением, удивлением (как красиво! ура!) — <b>восклицательный знак</b>."}, "addr": {"title": "Обращение", "text": "<b>Обращение</b> — это слово, которым <b>называют того, к кому обращаются</b>: по имени или по названию (Вира, ребята, бабушка). Оно выделяется запятыми и <b>не бывает подлежащим</b>."}, "phr": {"title": "Предложение или словосочетание", "text": "<b>Предложение</b> выражает законченную мысль: есть <b>о ком</b> говорится и <b>что</b> говорится (щенок лает). <b>Словосочетание</b> только называет: весёлый щенок."}, "mem": {"title": "Главные члены", "text": "1. Найди <b>действие</b>: что делает? что сделал? — это <b>сказуемое</b>, <b>две черты</b>.<br>2. Спроси: <b>кто? или что?</b> это делает — это <b>подлежащее</b>, <b>одна черта</b>.<br>3. Слово <b>с предлогом</b> (у окна, на поляну) подлежащим не бывает. Слово, которое отвечает на <b>кого? что?</b> после действия (ловит муху), — тоже не подлежащее."}, "syn": {"title": "Синонимы", "text": "<b>Синонимы</b> — слова, <b>близкие по значению</b>, но разные по звучанию: смелый — храбрый, бежать — мчаться."}, "ant": {"title": "Антонимы", "text": "<b>Антонимы</b> — слова с <b>противоположным значением</b>: день — ночь, горячий — холодный."}, "fig": {"title": "Прямое и переносное", "text": "<b>Прямое</b> значение — как есть на самом деле: колючий ёж (у ежа иголки). <b>Переносное</b> — похоже по какому-то признаку: колючий ветер (не иголки, а как будто колет)."}, "sec": {"title": "Второстепенные члены", "text": "Второстепенные члены <b>поясняют</b> главные или другие второстепенные. 1. Найди <b>основу</b>: сказуемое и подлежащее. 2. Задавай <b>вопросы от главных слов</b>: какой? что? кого? где? когда? куда? как? 3. Слово, которое отвечает на вопрос, — второстепенный член. Подчёркиваем <b>пунктиром</b>. Предлог (на, в, у) подчёркиваем вместе со словом."}, "mnog": {"title": "Многозначные слова", "text": "У <b>многозначного</b> слова <b>несколько значений</b>: ключ от двери и ключ — родник. Какое значение — подскажут <b>соседние слова</b> в предложении."}, "trio": {"title": "Многозначные слова", "text": "Одно и то же <b>многозначное</b> слово называет разные, но <b>чем-то похожие</b> предметы: нос человека и нос корабля (оба впереди). Подставь слово во все три — должно подойти везде."}, "fraz": {"title": "Фразеологизмы", "text": "<b>Фразеологизм</b> — выражение, которое понимают <b>целиком, а не по словам</b>. «Бить баклуши» — это не бить, а бездельничать."}};

